function post(a) {
    r = {
        url: a.url,
        type: "post",
        dataType: "json",
        contentType: "json/application",
        data: a.data,
        success: function (b) {
            a.success(b)
        },
        error: function (b) {
            a.error(b)
        }
    };
    let e = localStorage.getItem("token");
    null != e && e.length > 0 && (r.headers = {token: e}), $.ajax(r)
};